using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class BusbarSelectionForm:Form {
readonly Project project;readonly Board board;readonly BusbarRequirements requirements;string context;List<BusbarRating> items;readonly ComboBox pick=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=490};readonly TextBox details=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill};readonly List<Action> readers=new List<Action>();readonly DataGridView catalog=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.AllCells};public bool Changed{get;private set;}
public BusbarSelectionForm(Project p,Board b){project=p;board=b;if(b==null||b.Circuits.Count==0)throw new InvalidDataException("Selecione quadro com circuitos.");requirements=b.BusbarSelection==null?new BusbarRequirements():b.BusbarSelection.Requirements.Copy();context=b.BusbarSelection==null?BusbarSelection.Context(p,b):b.BusbarSelection.ElectricalContext;items=BusbarSelection.ReferenceCatalog();if(b.BusbarSelection!=null&&b.BusbarSelection.Rating!=null&&!items.Any(x=>x.Reference==b.BusbarSelection.Rating.Reference))items.Add(b.BusbarSelection.Rating.Copy());Text="Conjunto de barras / busway do quadro — "+b.Id;Size=new Size(1500,980);MinimumSize=new Size(1200,800);Font=new Font("Segoe UI",10);var split=new SplitContainer{Dock=DockStyle.Fill};split.Size=new Size(1460,870);split.SplitterDistance=665;var tabs=new TabControl{Dock=DockStyle.Fill};var inputs=new TabPage("Exigências e condições");inputs.Controls.Add(TypedFields.Create(requirements,readers));var list=new TabPage("Catálogo rastreável");list.Controls.Add(catalog);tabs.TabPages.AddRange(new[]{inputs,list});split.Panel1.Controls.Add(tabs);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=160};bar.Controls.Add(pick);Add(bar,"Importar catálogo CSV",()=>{using(var d=new OpenFileDialog{Filter="Conjuntos CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var copy=BusbarSelection.Import(d.FileName);items=copy;RefreshCatalog();}});Add(bar,"Exportar catálogo CSV",()=>{using(var d=new SaveFileDialog{Filter="Conjuntos CSV|*.csv"})if(d.ShowDialog(this)==DialogResult.OK)BusbarSelection.Export(items,d.FileName);});Add(bar,"Menor nominal que atende",()=>Recommend());Add(bar,"Avaliar cópia",()=>EvaluateDraft(false));Add(bar,"Salvar seleção",()=>EvaluateDraft(true));Add(bar,"Revincular exigências",()=>{Read();context=BusbarSelection.Context(project,board);details.Text="Exigências revinculadas à fonte/rede/fluxo atuais na cópia. Confira as evidências de corrente, curto e condições antes de salvar.";});Add(bar,"Remover seleção",()=>{board.BusbarSelection=null;Changed=true;details.Text="Seleção removida.";});split.Panel2.Controls.Add(details);split.Panel2.Controls.Add(bar);Controls.Add(split);RefreshCatalog();if(b.BusbarSelection!=null&&b.BusbarSelection.Rating!=null)pick.SelectedItem=items.FirstOrDefault(x=>x.Reference==b.BusbarSelection.Rating.Reference);details.Text="Seleção nominal e suportabilidade do conjunto no quadro. Maior fase RMS, sem usar média. FluxoF22 fornece fundamental; só usar comoRMS mediante regime senoidal documentado, ou informeRMS externo com correções de harmônicas. Neutro exige rating próprio; catálogo de exemplo3L+PE não contémN. Icw/tempo eIpk verificados separadamente, sem extrapolarIcw por√t ou presumir limitação de proteção. Registre montagem, ambiente, THD e envelope de curto/tempo TOTAL. O conjunto não altera parâmetros dos cabos nem calcula queda do trecho busway. Catálogo real de poucas linhas CanalisKTA04/2026; configuração/instalação completas exigem documentação específica.";}
void Add(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true};b.Click+=(s,e)=>{try{action();}catch(Exception ex){details.Text="Operação recusada: "+ex.Message;}};parent.Controls.Add(b);}
void Read(){foreach(var read in readers)read();requirements.Validate();}
void RefreshCatalog(){pick.DataSource=null;pick.DisplayMember="Reference";pick.DataSource=items;pick.SelectedIndex=-1;catalog.DataSource=null;catalog.DataSource=items.ToList();foreach(DataGridViewColumn col in catalog.Columns){switch(col.Name){case "Reference":col.HeaderText="Referência";break;case "Kind":col.HeaderText="Tipo";break;case "Configuration":col.HeaderText="Configuração";break;case "HasNeutral":col.HeaderText="Tem N";break;case "RatedCurrentA":col.HeaderText="In (A)";break;case "NeutralRatedA":col.HeaderText="In N (A)";break;case "OperatingVoltageMaxV":col.HeaderText="Ue máx (V)";break;case "FrequencyHz":col.HeaderText="f (Hz)";break;case "IcwKA":col.HeaderText="Icw (kA)";break;case "IcwSeconds":col.HeaderText="t Icw (s)";break;case "IpkKA":col.HeaderText="Ipk (kA)";break;case "Source":col.HeaderText="Fonte";break;case "DataVersion":col.HeaderText="Versão";break;case "Conditions":col.HeaderText="Condições";break;}}}
public void SelectRating(string reference){var selected=items.FirstOrDefault(x=>x.Reference==reference);if(selected==null)throw new InvalidDataException("Referência fora do catálogo.");pick.SelectedItem=selected;}
public BusbarResult EvaluateDraft(bool commit){Read();var selected=pick.SelectedItem as BusbarRating;if(selected==null)throw new InvalidDataException("Escolha um conjunto do catálogo.");var binding=new BusbarBinding{Rating=selected.Copy(),Requirements=requirements.Copy(),ElectricalContext=context};binding.Validate();var result=BusbarSelection.Evaluate(project,board,binding);details.Text=result.Status+"\r\n"+result.Detail;if(commit){board.BusbarSelection=binding;Changed=true;}return result;}
public BusbarRating Recommend(){Read();if(context!=BusbarSelection.Context(project,board))throw new InvalidDataException("Fonte/rede alteradas; confira dados e revincule exigências explicitamente.");var row=BusbarSelection.Recommend(project,board,items,requirements);if(row==null){details.Text="Nenhum candidato atende aos dados/comparações disponíveis.";return null;}pick.SelectedItem=row;EvaluateDraft(false);return row;}
}
partial class Studio{void ConfigureBusbars(){using(var f=new BusbarSelectionForm(project,board)){f.ShowDialog(this);if(f.Changed)Change();}}}
}
